-- ======================================================== 0003_rate_limits.sql
-- Fixed-window rate limiting for auth endpoints (PRODUCTION-BRIEF §3.1).
-- Called only by the server with the service role.

create table if not exists public.rate_limits (
  key          text primary key,
  hits         int not null,
  window_start timestamptz not null
);
alter table public.rate_limits enable row level security;
revoke all on public.rate_limits from anon, authenticated;

-- Returns true while the caller is within p_max hits per p_window_seconds.
create or replace function public.consume_rate_limit(p_key text, p_max int, p_window_seconds int)
returns boolean
language plpgsql security definer set search_path = public as $$
declare
  v_hits int;
begin
  insert into public.rate_limits as rl (key, hits, window_start)
  values (p_key, 1, now())
  on conflict (key) do update set
    hits = case when rl.window_start <= now() - make_interval(secs => p_window_seconds)
                then 1 else rl.hits + 1 end,
    window_start = case when rl.window_start <= now() - make_interval(secs => p_window_seconds)
                then now() else rl.window_start end
  returning hits into v_hits;
  return v_hits <= p_max;
end $$;

revoke execute on function public.consume_rate_limit(text, int, int) from public, anon, authenticated;
grant execute on function public.consume_rate_limit(text, int, int) to service_role;


-- ======================================================== 0004_ledger_month_close.sql
-- Capital 50 AI — Phase 2: holdings, append-only ledger, month close (PRODUCTION-BRIEF §4, §5.1)
-- Balances are sums of ledger_entries. Nothing ever updates or deletes a ledger row.
-- Safe to re-run.

-- ------------------------------------------------------------------ holdings
create table if not exists public.holdings (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references auth.users(id) on delete restrict,
  strategy_id uuid not null references public.strategies(id),
  opened_at   timestamptz not null default now(),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  unique (user_id, strategy_id)
);

drop trigger if exists holdings_updated on public.holdings;
create trigger holdings_updated before update on public.holdings
  for each row execute function public.set_updated_at();

-- ------------------------------------------------------------ ledger_entries
do $$ begin
  create type public.ledger_type as enum
    ('deposit', 'withdrawal', 'profit', 'loss', 'fee', 'affiliate_commission', 'affiliate_payout', 'adjustment');
exception when duplicate_object then null; end $$;

-- `ym` is the month an entry belongs to. For a deposit or withdrawal it is the first month the
-- money counts in; for profit/loss/fee it is the month that was closed.
create table if not exists public.ledger_entries (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null references auth.users(id) on delete restrict,
  holding_id      uuid references public.holdings(id) on delete restrict,
  type            public.ledger_type not null,
  amount          numeric(18,2) not null check (amount <> 0),
  ym              date not null check (extract(day from ym) = 1),
  ref_type        text,
  ref_id          text,
  idempotency_key text not null unique,
  meta            jsonb not null default '{}'::jsonb,
  created_at      timestamptz not null default now(),
  constraint ledger_sign check (
    (type in ('deposit', 'profit', 'affiliate_commission') and amount > 0) or
    (type in ('withdrawal', 'loss', 'fee', 'affiliate_payout') and amount < 0) or
    type = 'adjustment'),
  constraint ledger_holding_required check (
    holding_id is not null or type in ('affiliate_commission', 'affiliate_payout', 'adjustment'))
);
create index if not exists ledger_entries_user_ym on public.ledger_entries (user_id, ym);
create index if not exists ledger_entries_holding_ym on public.ledger_entries (holding_id, ym);

-- ------------------------------------------------------------- month_closes
create table if not exists public.month_closes (
  ym           date primary key check (extract(day from ym) = 1),
  closed_at    timestamptz not null default now(),
  closed_by    uuid references auth.users(id),
  holdings     int not null,
  total_profit numeric(18,2) not null,
  total_fees   numeric(18,2) not null
);

-- ---------------------------------------------------------- ledger guards
-- Append-only. The only exception is purge_demo_data(), which sets a transaction-local flag.
create or replace function public.ledger_append_only() returns trigger
language plpgsql as $$
begin
  if current_setting('c50.ledger_purge', true) = 'on' then
    return old;
  end if;
  raise exception 'ledger_entries is append-only';
end $$;

drop trigger if exists ledger_no_change on public.ledger_entries;
create trigger ledger_no_change before update or delete on public.ledger_entries
  for each row execute function public.ledger_append_only();
drop trigger if exists ledger_no_truncate on public.ledger_entries;
create trigger ledger_no_truncate before truncate on public.ledger_entries
  for each statement execute function public.audit_log_immutable();

-- Money can't be added to (or taken from) a month that is already closed, and a deposit can't
-- slip in while a close is running.
create or replace function public.ledger_check_open_month() returns trigger
language plpgsql as $$
declare
  v_last date;
begin
  if new.type in ('deposit', 'withdrawal') then
    perform pg_advisory_xact_lock(hashtext('c50.month_close'));
    select max(ym) into v_last from public.month_closes;
    if v_last is not null and new.ym <= v_last then
      raise exception 'Month % is already closed; % must count from a later month',
        to_char(new.ym, 'YYYY-MM'), new.type;
    end if;
  end if;
  return new;
end $$;

drop trigger if exists ledger_open_month on public.ledger_entries;
create trigger ledger_open_month before insert on public.ledger_entries
  for each row execute function public.ledger_check_open_month();

-- -------------------------------------------------------------- month close
-- For each holding open in month p_ym, with r = the published return for that strategy/month:
--   value_start = everything before p_ym + deposits/withdrawals that count from p_ym
--   profit      = round(value_start × r / 100, 2)          (negative = loss)
--   fee         = round(max(0, profit) × 2.5%, 2)
-- Writes profit|loss and fee entries keyed close:{ym}:{holding}:{type}. Re-running is a no-op.
-- Affiliate commissions are added in Phase 6.
create or replace function public.close_month(p_ym date, p_actor uuid default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_ym     text := to_char(p_ym, 'YYYY-MM');
  v_last   date;
  h        record;
  v_start  numeric(18,2);
  v_r      numeric(7,3);
  v_profit numeric(18,2);
  v_fee    numeric(18,2);
  v_n      int := 0;
  v_tp     numeric(18,2) := 0;
  v_tf     numeric(18,2) := 0;
  v_result jsonb;
begin
  if p_ym is null or extract(day from p_ym) <> 1 then
    raise exception 'close_month needs the first day of a month, got %', p_ym;
  end if;
  perform pg_advisory_xact_lock(hashtext('c50.month_close'));

  if exists (select 1 from month_closes where ym = p_ym) then
    select jsonb_build_object('ym', v_ym, 'already_closed', true, 'holdings', holdings,
                              'total_profit', total_profit, 'total_fees', total_fees)
      into v_result from month_closes where ym = p_ym;
    return v_result;
  end if;

  select max(ym) into v_last from month_closes;
  if v_last is not null and p_ym < v_last then
    raise exception 'Cannot close %: % is already closed', v_ym, to_char(v_last, 'YYYY-MM');
  end if;
  -- no gaps: every month after the first close must be closed in order
  if v_last is not null and p_ym <> (v_last + interval '1 month')::date then
    raise exception 'Close % first', to_char(v_last + interval '1 month', 'YYYY-MM');
  end if;
  if p_ym >= date_trunc('month', now() at time zone 'Asia/Karachi')::date then
    raise exception 'Cannot close %: the month has not ended yet', v_ym;
  end if;

  for h in
    select ho.id, ho.user_id, ho.strategy_id, s.slug
      from holdings ho join strategies s on s.id = ho.strategy_id
     order by ho.id
  loop
    select coalesce(sum(amount), 0) into v_start
      from ledger_entries
     where holding_id = h.id
       and (ym < p_ym or (ym = p_ym and type in ('deposit', 'withdrawal')));
    continue when v_start <= 0;

    select return_pct into v_r from strategy_returns
     where strategy_id = h.strategy_id and ym = p_ym and status = 'published';
    if v_r is null then
      raise exception 'No published % return for %; publish it before closing the month', h.slug, v_ym;
    end if;

    v_profit := round(v_start * v_r / 100, 2);
    v_fee    := round(greatest(v_profit, 0) * 0.025, 2);

    if v_profit <> 0 then
      insert into ledger_entries (user_id, holding_id, type, amount, ym, ref_type, ref_id, idempotency_key, meta)
      values (h.user_id, h.id, case when v_profit > 0 then 'profit' else 'loss' end::ledger_type, v_profit, p_ym,
              'month_close', v_ym,
              format('close:%s:%s:%s', v_ym, h.id, case when v_profit > 0 then 'profit' else 'loss' end),
              jsonb_build_object('r', v_r, 'value_start', v_start))
      on conflict (idempotency_key) do nothing;
    end if;
    if v_fee > 0 then
      insert into ledger_entries (user_id, holding_id, type, amount, ym, ref_type, ref_id, idempotency_key, meta)
      values (h.user_id, h.id, 'fee', -v_fee, p_ym, 'month_close', v_ym,
              format('close:%s:%s:fee', v_ym, h.id),
              jsonb_build_object('rate', 0.025, 'profit', v_profit))
      on conflict (idempotency_key) do nothing;
    end if;

    v_n  := v_n + 1;
    v_tp := v_tp + v_profit;
    v_tf := v_tf + v_fee;
  end loop;

  insert into month_closes (ym, closed_by, holdings, total_profit, total_fees)
  values (p_ym, p_actor, v_n, v_tp, v_tf);

  v_result := jsonb_build_object('ym', v_ym, 'already_closed', false, 'holdings', v_n,
                                 'total_profit', v_tp, 'total_fees', v_tf);
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, after)
  values (p_actor, case when p_actor is null then 'system' else 'staff' end,
          'month.close', 'month_closes', v_ym, v_result);
  return v_result;
end $$;

-- ------------------------------------------------------------- demo purge
-- Removes the demo investor (mobile 300 1234567) and every ledger row it has. Run before launch:
--   select public.purge_demo_data();
create or replace function public.purge_demo_data() returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid;
begin
  select id into v_uid from auth.users where phone = '923001234567';
  if v_uid is null then return; end if;
  perform set_config('c50.ledger_purge', 'on', true);
  delete from ledger_entries where user_id = v_uid;
  delete from holdings where user_id = v_uid;
  delete from auth.users where id = v_uid;
  perform set_config('c50.ledger_purge', 'off', true);
  insert into audit_log (actor_role, action, entity, entity_id, reason)
  values ('system', 'demo.purge', 'auth.users', v_uid::text, 'Demo account and sample money removed');
end $$;

-- ---------------------------------------------------------------------- RLS
alter table public.holdings       enable row level security;
alter table public.ledger_entries enable row level security;
alter table public.month_closes   enable row level security;

drop policy if exists holdings_own_read on public.holdings;
create policy holdings_own_read on public.holdings
  for select to authenticated using (user_id = auth.uid());

drop policy if exists ledger_own_read on public.ledger_entries;
create policy ledger_own_read on public.ledger_entries
  for select to authenticated using (user_id = auth.uid());

drop policy if exists month_closes_read on public.month_closes;
create policy month_closes_read on public.month_closes
  for select to authenticated using (true);

revoke insert, update, delete on public.holdings, public.ledger_entries, public.month_closes
  from anon, authenticated;
revoke execute on function public.close_month(date, uuid) from public, anon, authenticated;
revoke execute on function public.purge_demo_data() from public, anon, authenticated;
grant execute on function public.close_month(date, uuid) to service_role;


-- ======================================================== 0005_kyc_staff.sql
-- Capital 50 AI — Phase 3: KYC applications, documents (private storage), staff and the review decision.
-- PRODUCTION-BRIEF §3.6, §5.6, §6.2. Safe to re-run.

-- ---------------------------------------------------------------------- staff
do $$ begin
  create type public.staff_role as enum ('owner', 'compliance', 'finance', 'support');
exception when duplicate_object then null; end $$;

create table if not exists public.staff_members (
  user_id    uuid primary key references auth.users(id) on delete cascade,
  role       public.staff_role not null,
  active     boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
drop trigger if exists staff_members_updated on public.staff_members;
create trigger staff_members_updated before update on public.staff_members
  for each row execute function public.set_updated_at();

-- Make an existing email login a staff member:  select public.grant_staff('you@example.com', 'owner');
create or replace function public.grant_staff(p_email text, p_role public.staff_role) returns text
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid;
begin
  select id into v_uid from auth.users where lower(email) = lower(trim(p_email));
  if v_uid is null then
    raise exception 'No login with email %. Create it first in Authentication > Users > Add user.', p_email;
  end if;
  insert into staff_members (user_id, role, active) values (v_uid, p_role, true)
  on conflict (user_id) do update set role = excluded.role, active = true;
  insert into audit_log (actor_role, action, entity, entity_id, after)
  values ('system', 'staff.grant', 'staff_members', v_uid::text, jsonb_build_object('email', p_email, 'role', p_role));
  return format('%s is now %s staff. They sign in at /admin/login.', p_email, p_role);
end $$;

-- ------------------------------------------------------------- applications
do $$ begin
  create type public.kyc_status as enum ('draft', 'review', 'verified', 'rejected');
exception when duplicate_object then null; end $$;

-- One row per attempt; history is kept. The latest row is the current one.
create table if not exists public.kyc_applications (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references auth.users(id) on delete restrict,
  status           public.kyc_status not null default 'draft',
  personal         jsonb not null default '{}'::jsonb,
  financial        jsonb not null default '{}'::jsonb,
  pep              boolean,
  edd              boolean not null default false,
  cnic_hash        text,
  provider_ref     text,
  provider_result  jsonb,
  rejection_reason text,
  submitted_at     timestamptz,
  decided_at       timestamptz,
  decided_by       uuid references auth.users(id),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create index if not exists kyc_applications_user on public.kyc_applications (user_id, created_at desc);
create index if not exists kyc_applications_status on public.kyc_applications (status, submitted_at);
-- One CNIC, one investor: no two people can be under review or verified with the same CNIC.
create unique index if not exists kyc_applications_cnic_once on public.kyc_applications (cnic_hash)
  where status in ('review', 'verified');
-- At most one open (draft or review) application per investor.
create unique index if not exists kyc_applications_one_open on public.kyc_applications (user_id)
  where status in ('draft', 'review');

drop trigger if exists kyc_applications_updated on public.kyc_applications;
create trigger kyc_applications_updated before update on public.kyc_applications
  for each row execute function public.set_updated_at();

do $$ begin
  create type public.kyc_doc_kind as enum ('cnic_front', 'cnic_back', 'selfie');
exception when duplicate_object then null; end $$;

create table if not exists public.kyc_documents (
  id             uuid primary key default gen_random_uuid(),
  application_id uuid not null references public.kyc_applications(id) on delete restrict,
  user_id        uuid not null references auth.users(id) on delete restrict,
  kind           public.kyc_doc_kind not null,
  storage_path   text not null unique,
  mime           text not null,
  size_bytes     int not null,
  sha256         text not null,
  created_at     timestamptz not null default now()
);
create index if not exists kyc_documents_app on public.kyc_documents (application_id, kind, created_at desc);

-- Private bucket. Only the server (service role) reads or writes it; staff get 5-minute signed links.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('kyc', 'kyc', false, 5242880, array['image/jpeg', 'image/png', 'application/pdf'])
on conflict (id) do update set public = false, file_size_limit = 5242880,
  allowed_mime_types = array['image/jpeg', 'image/png', 'application/pdf'];

-- ------------------------------------------------------------- the decision
-- Approve or reject an application under review. Only active owner/compliance staff.
-- Approval copies the CNIC name and city onto the profile (the name is locked from then on).
create or replace function public.kyc_decide(p_application uuid, p_staff uuid, p_approve boolean, p_reason text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_app   kyc_applications%rowtype;
  v_role  staff_role;
  v_after jsonb;
begin
  select role into v_role from staff_members where user_id = p_staff and active;
  if v_role is null or v_role not in ('owner', 'compliance') then
    raise exception 'Only owner or compliance staff can decide KYC';
  end if;

  select * into v_app from kyc_applications where id = p_application for update;
  if not found then raise exception 'Application not found'; end if;
  if v_app.status <> 'review' then
    raise exception 'Application is %, not under review', v_app.status;
  end if;
  if not p_approve and length(trim(coalesce(p_reason, ''))) < 5 then
    raise exception 'A rejection needs a reason the investor can act on';
  end if;
  if p_approve and v_app.user_id = p_staff then
    raise exception 'Staff cannot approve their own application';
  end if;

  update kyc_applications
     set status = case when p_approve then 'verified' else 'rejected' end::kyc_status,
         rejection_reason = case when p_approve then null else trim(p_reason) end,
         decided_at = now(), decided_by = p_staff
   where id = p_application;

  if p_approve then
    update profiles set full_name = v_app.personal->>'fullName', city = v_app.personal->>'city'
     where user_id = v_app.user_id;
  end if;

  v_after := jsonb_build_object('status', case when p_approve then 'verified' else 'rejected' end,
                                'reason', case when p_approve then null else trim(p_reason) end,
                                'pep', v_app.pep);
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, before, after, reason)
  values (p_staff, v_role::text, case when p_approve then 'kyc.approve' else 'kyc.reject' end,
          'kyc_applications', p_application::text, jsonb_build_object('status', v_app.status), v_after,
          nullif(trim(coalesce(p_reason, '')), ''));
  return v_after;
end $$;

-- ---------------------------------------------------------------------- RLS
alter table public.staff_members    enable row level security;
alter table public.kyc_applications enable row level security;
alter table public.kyc_documents    enable row level security;

drop policy if exists kyc_own_read on public.kyc_applications;
create policy kyc_own_read on public.kyc_applications
  for select to authenticated using (user_id = auth.uid());
drop policy if exists kyc_docs_own_read on public.kyc_documents;
create policy kyc_docs_own_read on public.kyc_documents
  for select to authenticated using (user_id = auth.uid());

revoke all on public.staff_members from anon, authenticated;
revoke insert, update, delete on public.kyc_applications, public.kyc_documents from anon, authenticated;
revoke execute on function public.kyc_decide(uuid, uuid, boolean, text) from public, anon, authenticated;
revoke execute on function public.grant_staff(text, public.staff_role) from public, anon, authenticated;
grant execute on function public.kyc_decide(uuid, uuid, boolean, text) to service_role;


-- ======================================================== 0006_deposits.sql
-- Capital 50 AI — Phase 4: deposits (PRODUCTION-BRIEF §5.4). Safe to re-run.
-- A deposit is credited exactly once, only by credit_deposit(): from a signature-verified provider
-- notification or from two-person staff confirmation of a bank transfer. Never from a browser redirect.

do $$ begin
  create type public.deposit_method as enum ('jazzcash', 'easypaisa', 'bank', 'usdt');
exception when duplicate_object then null; end $$;
do $$ begin
  create type public.deposit_status as enum ('pending', 'paid', 'failed', 'expired', 'refunded');
exception when duplicate_object then null; end $$;

create table if not exists public.deposits (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users(id) on delete restrict,
  strategy_id   uuid not null references public.strategies(id),
  amount        numeric(18,2) not null check (amount >= 5000 and amount <= 10000000),
  method        public.deposit_method not null,
  status        public.deposit_status not null default 'pending',
  reference     text not null unique,              -- our order reference (bank memo / provider order id)
  provider_ref  text unique,                       -- provider's transaction id, once known
  mode          text not null default 'sandbox' check (mode in ('sandbox', 'live')),
  meta          jsonb not null default '{}'::jsonb, -- e.g. USDT rate and invoice
  approvals     jsonb not null default '[]'::jsonb, -- bank transfer confirmations
  status_note   text,
  paid_at       timestamptz,
  effective_ym  date,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index if not exists deposits_user on public.deposits (user_id, created_at desc);
create index if not exists deposits_pending on public.deposits (method, status, created_at);

drop trigger if exists deposits_updated on public.deposits;
create trigger deposits_updated before update on public.deposits
  for each row execute function public.set_updated_at();

-- Every provider notification and staff action, exactly as received. Append-only.
create table if not exists public.payment_events (
  id           uuid primary key default gen_random_uuid(),
  provider     text not null,
  deposit_id   uuid references public.deposits(id),
  signature_ok boolean not null,
  outcome      text not null,
  payload      jsonb not null,
  received_at  timestamptz not null default now()
);
create index if not exists payment_events_deposit on public.payment_events (deposit_id, received_at);
drop trigger if exists payment_events_no_change on public.payment_events;
create trigger payment_events_no_change before update or delete on public.payment_events
  for each row execute function public.audit_log_immutable();

-- Company settings readable by the server (e.g. the bank account investors pay into).
create table if not exists public.app_settings (
  key        text primary key,
  value      jsonb not null,
  updated_at timestamptz not null default now()
);
insert into public.app_settings (key, value) values
  ('bank_account', '{"bank":"","title":"","iban":"","note":"Set your company bank account: update app_settings where key = ''bank_account''."}')
on conflict (key) do nothing;

-- ------------------------------------------------------------- credit
-- Money paid during a month starts earning the next month (brief §5.1 rule 6). One place to change it.
create or replace function public.deposit_effective_ym(p_paid_at timestamptz) returns date
language sql stable as $$
  select (date_trunc('month', p_paid_at at time zone 'Asia/Karachi') + interval '1 month')::date
$$;

-- Marks a pending deposit paid and writes its ledger entry. Calling it again returns the same
-- result and writes nothing (so replayed notifications are harmless).
create or replace function public.credit_deposit(p_deposit uuid, p_actor uuid, p_source text, p_provider_ref text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  d       deposits%rowtype;
  v_hold  uuid;
  v_ym    date;
  v_now   timestamptz := now();
begin
  select * into d from deposits where id = p_deposit for update;
  if not found then raise exception 'Deposit not found'; end if;
  if d.status = 'paid' then
    return jsonb_build_object('status', 'paid', 'already', true, 'effective_ym', to_char(d.effective_ym, 'YYYY-MM'));
  end if;
  if d.status <> 'pending' then
    raise exception 'Deposit % is %, not pending', d.reference, d.status;
  end if;
  -- one provider transaction can only ever pay for one deposit
  if p_provider_ref is not null and exists (select 1 from deposits where provider_ref = p_provider_ref and id <> d.id) then
    raise exception 'Payment % was already used for deposit %', p_provider_ref,
      (select reference from deposits where provider_ref = p_provider_ref and id <> d.id limit 1);
  end if;

  v_ym := deposit_effective_ym(v_now);
  insert into holdings (user_id, strategy_id) values (d.user_id, d.strategy_id)
  on conflict (user_id, strategy_id) do nothing;
  select id into v_hold from holdings where user_id = d.user_id and strategy_id = d.strategy_id;

  update deposits set status = 'paid', paid_at = v_now, effective_ym = v_ym,
         provider_ref = coalesce(p_provider_ref, provider_ref)
   where id = d.id;

  insert into ledger_entries (user_id, holding_id, type, amount, ym, ref_type, ref_id, idempotency_key, meta)
  values (d.user_id, v_hold, 'deposit', d.amount, v_ym, 'deposit', d.id::text, 'dep:' || d.id,
          jsonb_build_object('method', d.method, 'reference', d.reference, 'source', p_source,
                             'day', extract(day from v_now at time zone 'Asia/Karachi')::int));

  insert into audit_log (actor_id, actor_role, action, entity, entity_id, after)
  values (p_actor, case when p_actor is null then 'system' else 'staff' end, 'deposit.credit', 'deposits', d.id::text,
          jsonb_build_object('amount', d.amount, 'method', d.method, 'source', p_source,
                             'provider_ref', p_provider_ref, 'effective_ym', to_char(v_ym, 'YYYY-MM')));
  return jsonb_build_object('status', 'paid', 'already', false, 'effective_ym', to_char(v_ym, 'YYYY-MM'));
end $$;

-- Pending -> failed/expired (from a verified provider notification or staff). Paid deposits are untouched.
create or replace function public.close_deposit(p_deposit uuid, p_status deposit_status, p_actor uuid, p_note text)
returns text
language plpgsql security definer set search_path = public as $$
declare
  d deposits%rowtype;
begin
  if p_status not in ('failed', 'expired') then raise exception 'close_deposit only fails or expires'; end if;
  select * into d from deposits where id = p_deposit for update;
  if not found then raise exception 'Deposit not found'; end if;
  if d.status <> 'pending' then return d.status::text; end if;
  update deposits set status = p_status, status_note = p_note where id = d.id;
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, after, reason)
  values (p_actor, case when p_actor is null then 'system' else 'staff' end, 'deposit.' || p_status, 'deposits',
          d.id::text, jsonb_build_object('amount', d.amount, 'method', d.method), p_note);
  return p_status::text;
end $$;

-- Bank transfers: two different owner/finance staff confirm the same bank statement reference.
-- The second confirmation credits the deposit.
create or replace function public.confirm_bank_deposit(p_deposit uuid, p_staff uuid, p_bank_ref text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  d      deposits%rowtype;
  v_role staff_role;
  v_ref  text := upper(regexp_replace(coalesce(p_bank_ref, ''), '\s', '', 'g'));
  v_first jsonb;
begin
  select role into v_role from staff_members where user_id = p_staff and active;
  if v_role is null or v_role not in ('owner', 'finance') then
    raise exception 'Only owner or finance staff can confirm bank deposits';
  end if;
  if length(v_ref) < 4 then raise exception 'Enter the transaction reference from the bank statement'; end if;

  select * into d from deposits where id = p_deposit for update;
  if not found then raise exception 'Deposit not found'; end if;
  if d.method <> 'bank' then raise exception 'Not a bank transfer'; end if;
  if d.status <> 'pending' then raise exception 'Deposit is %, not pending', d.status; end if;
  if d.user_id = p_staff then raise exception 'Staff cannot confirm their own deposit'; end if;
  -- one bank transaction can only ever pay for one deposit
  if exists (select 1 from deposits where provider_ref = 'BANK:' || v_ref and id <> d.id) then
    raise exception 'Bank reference % was already used for deposit %', v_ref,
      (select reference from deposits where provider_ref = 'BANK:' || v_ref and id <> d.id limit 1);
  end if;

  v_first := d.approvals -> 0;
  if v_first is null then
    update deposits set approvals = jsonb_build_array(jsonb_build_object('staff', p_staff, 'bank_ref', v_ref, 'at', now()))
     where id = d.id;
    insert into audit_log (actor_id, actor_role, action, entity, entity_id, after)
    values (p_staff, v_role::text, 'deposit.bank_confirm_1', 'deposits', d.id::text, jsonb_build_object('bank_ref', v_ref));
    return jsonb_build_object('status', 'pending', 'confirmations', 1);
  end if;

  if (v_first->>'staff')::uuid = p_staff then
    raise exception 'A second, different staff member must confirm this deposit';
  end if;
  if v_first->>'bank_ref' <> v_ref then
    raise exception 'Bank reference does not match the first confirmation (%)', v_first->>'bank_ref';
  end if;
  update deposits set approvals = approvals || jsonb_build_array(jsonb_build_object('staff', p_staff, 'bank_ref', v_ref, 'at', now()))
   where id = d.id;
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, after)
  values (p_staff, v_role::text, 'deposit.bank_confirm_2', 'deposits', d.id::text, jsonb_build_object('bank_ref', v_ref));
  return credit_deposit(d.id, p_staff, 'bank_two_person', 'BANK:' || v_ref);
end $$;

-- ---------------------------------------------------------------------- RLS
alter table public.deposits       enable row level security;
alter table public.payment_events enable row level security;
alter table public.app_settings   enable row level security;

drop policy if exists deposits_own_read on public.deposits;
create policy deposits_own_read on public.deposits
  for select to authenticated using (user_id = auth.uid());

revoke insert, update, delete on public.deposits from anon, authenticated;
revoke all on public.payment_events, public.app_settings from anon, authenticated;
revoke execute on function public.credit_deposit(uuid, uuid, text, text),
                           public.close_deposit(uuid, deposit_status, uuid, text),
                           public.confirm_bank_deposit(uuid, uuid, text)
  from public, anon, authenticated;
grant execute on function public.credit_deposit(uuid, uuid, text, text),
                          public.close_deposit(uuid, deposit_status, uuid, text),
                          public.confirm_bank_deposit(uuid, uuid, text)
  to service_role;


-- ======================================================== 0007_withdrawals.sql
-- Capital 50 AI — Phase 5: payout methods and withdrawals (PRODUCTION-BRIEF §3.4, §5.5). Safe to re-run.
-- Money leaves the ledger only in pay_withdrawal(): after KYC, a 24-hour-old payout method in the
-- investor's verified name, an SMS code, staff approval (two people above the threshold) and a
-- payment reference. Every step is audit-logged.

do $$ begin
  create type public.payout_type as enum ('jazz', 'easy', 'bank', 'usdt');
exception when duplicate_object then null; end $$;
do $$ begin
  create type public.withdrawal_status as enum ('requested', 'approved', 'paid', 'rejected', 'cancelled');
exception when duplicate_object then null; end $$;

create table if not exists public.payout_methods (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null references auth.users(id) on delete restrict,
  type           public.payout_type not null,
  account_enc    text not null,                 -- AES-256-GCM, key held by the server (C50_DATA_KEY)
  account_hint   text not null,                 -- e.g. "0300 •••• 4567", safe to show
  account_hash   text not null,                 -- keyed hash, to spot the same account twice
  bank           text,
  title          text not null,
  title_verified boolean not null default false,
  ready_at       timestamptz not null default now() + interval '24 hours',
  disabled_at    timestamptz,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index if not exists payout_methods_user on public.payout_methods (user_id);
create unique index if not exists payout_methods_once on public.payout_methods (user_id, account_hash) where disabled_at is null;
drop trigger if exists payout_methods_updated on public.payout_methods;
create trigger payout_methods_updated before update on public.payout_methods
  for each row execute function public.set_updated_at();

create table if not exists public.withdrawals (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references auth.users(id) on delete restrict,
  payout_method_id uuid not null references public.payout_methods(id),
  amount           numeric(18,2) not null check (amount >= 1000),
  status           public.withdrawal_status not null default 'requested',
  needs_approvals  int not null check (needs_approvals in (1, 2)),
  approvals        jsonb not null default '[]'::jsonb,
  tx_ref           text unique,
  reason           text,
  otp_verified_at  timestamptz not null,
  paid_at          timestamptz,
  paid_by          uuid references auth.users(id),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create index if not exists withdrawals_user on public.withdrawals (user_id, created_at desc);
create index if not exists withdrawals_open on public.withdrawals (status, created_at);
drop trigger if exists withdrawals_updated on public.withdrawals;
create trigger withdrawals_updated before update on public.withdrawals
  for each row execute function public.set_updated_at();

insert into public.app_settings (key, value) values ('withdrawal_two_approvals_above', '100000')
on conflict (key) do nothing;

-- ------------------------------------------------------------- balances
create or replace function public.ledger_balance(p_user uuid) returns numeric
language sql stable security definer set search_path = public as $$
  select coalesce(sum(amount), 0) from ledger_entries where user_id = p_user
$$;

-- What the investor can withdraw now: the ledger balance minus withdrawals already requested/approved.
create or replace function public.available_to_withdraw(p_user uuid) returns numeric
language sql stable security definer set search_path = public as $$
  select ledger_balance(p_user)
       - coalesce((select sum(amount) from withdrawals where user_id = p_user and status in ('requested', 'approved')), 0)
$$;

create or replace function public.kyc_verified(p_user uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((select status = 'verified' from kyc_applications where user_id = p_user
                   order by created_at desc limit 1), false)
$$;

-- ------------------------------------------------------------- request
create or replace function public.request_withdrawal(p_user uuid, p_method uuid, p_amount numeric, p_otp_at timestamptz)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  m        payout_methods%rowtype;
  v_limit  numeric;
  v_id     uuid;
begin
  perform pg_advisory_xact_lock(hashtext('c50.wd.' || p_user));  -- one money action per investor at a time
  if not kyc_verified(p_user) then raise exception 'Verify your identity (CNIC) before withdrawing'; end if;
  if p_otp_at is null or p_otp_at < now() - interval '10 minutes' then raise exception 'Confirm with the code sent to your phone'; end if;
  select * into m from payout_methods where id = p_method and user_id = p_user and disabled_at is null;
  if not found then raise exception 'Choose one of your payout methods'; end if;
  if m.ready_at > now() then raise exception 'This payout method unlocks at %', to_char(m.ready_at at time zone 'Asia/Karachi', 'DD Mon HH24:MI'); end if;
  if not m.title_verified then raise exception 'This account is not in your verified name'; end if;
  if p_amount is null or p_amount < 1000 then raise exception 'Minimum withdrawal is Rs 1,000'; end if;
  if p_amount <> round(p_amount, 2) then raise exception 'Invalid amount'; end if;
  if p_amount > available_to_withdraw(p_user) then raise exception 'That is more than your available balance'; end if;

  select coalesce((value #>> '{}')::numeric, 100000) into v_limit from app_settings where key = 'withdrawal_two_approvals_above';
  insert into withdrawals (user_id, payout_method_id, amount, needs_approvals, otp_verified_at)
  values (p_user, p_method, p_amount, case when p_amount > coalesce(v_limit, 100000) then 2 else 1 end, p_otp_at)
  returning id into v_id;
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, after)
  values (p_user, 'investor', 'withdrawal.request', 'withdrawals', v_id::text,
          jsonb_build_object('amount', p_amount, 'method', m.type, 'account', m.account_hint));
  return v_id;
end $$;

create or replace function public.cancel_withdrawal(p_user uuid, p_id uuid) returns text
language plpgsql security definer set search_path = public as $$
declare
  w withdrawals%rowtype;
begin
  select * into w from withdrawals where id = p_id and user_id = p_user for update;
  if not found then raise exception 'Withdrawal not found'; end if;
  if w.status <> 'requested' then raise exception 'This withdrawal is already %', w.status; end if;
  update withdrawals set status = 'cancelled' where id = p_id;
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, after)
  values (p_user, 'investor', 'withdrawal.cancel', 'withdrawals', p_id::text, jsonb_build_object('amount', w.amount));
  return 'cancelled';
end $$;

-- ------------------------------------------------------------- staff
create or replace function public.staff_money_role(p_staff uuid) returns staff_role
language plpgsql stable security definer set search_path = public as $$
declare v staff_role;
begin
  select role into v from staff_members where user_id = p_staff and active;
  if v is null or v not in ('owner', 'finance') then raise exception 'Only owner or finance staff can do this'; end if;
  return v;
end $$;

create or replace function public.approve_withdrawal(p_id uuid, p_staff uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_role staff_role := staff_money_role(p_staff);
  w      withdrawals%rowtype;
  v_n    int;
begin
  select * into w from withdrawals where id = p_id for update;
  if not found then raise exception 'Withdrawal not found'; end if;
  if w.status <> 'requested' then raise exception 'Withdrawal is %, not waiting for approval', w.status; end if;
  if w.user_id = p_staff then raise exception 'Staff cannot approve their own withdrawal'; end if;
  if exists (select 1 from jsonb_array_elements(w.approvals) a where (a->>'staff')::uuid = p_staff) then
    raise exception 'A second, different staff member must approve this withdrawal';
  end if;
  if not kyc_verified(w.user_id) then raise exception 'Investor is no longer KYC verified'; end if;
  if ledger_balance(w.user_id) < (select sum(amount) from withdrawals where user_id = w.user_id and status in ('requested', 'approved')) then
    raise exception 'Balance no longer covers this withdrawal';
  end if;

  v_n := jsonb_array_length(w.approvals) + 1;
  update withdrawals
     set approvals = approvals || jsonb_build_array(jsonb_build_object('staff', p_staff, 'at', now())),
         status = case when v_n >= needs_approvals then 'approved'::withdrawal_status else status end
   where id = p_id;
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, after)
  values (p_staff, v_role::text, 'withdrawal.approve', 'withdrawals', p_id::text,
          jsonb_build_object('approvals', v_n, 'needed', w.needs_approvals, 'amount', w.amount));
  return jsonb_build_object('approvals', v_n, 'needed', w.needs_approvals,
                            'status', case when v_n >= w.needs_approvals then 'approved' else 'requested' end);
end $$;

create or replace function public.reject_withdrawal(p_id uuid, p_staff uuid, p_reason text) returns text
language plpgsql security definer set search_path = public as $$
declare
  v_role staff_role := staff_money_role(p_staff);
  w      withdrawals%rowtype;
begin
  if length(trim(coalesce(p_reason, ''))) < 5 then raise exception 'Give a reason the investor can act on'; end if;
  select * into w from withdrawals where id = p_id for update;
  if not found then raise exception 'Withdrawal not found'; end if;
  if w.status not in ('requested', 'approved') then raise exception 'Withdrawal is already %', w.status; end if;
  update withdrawals set status = 'rejected', reason = trim(p_reason) where id = p_id;
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, after, reason)
  values (p_staff, v_role::text, 'withdrawal.reject', 'withdrawals', p_id::text, jsonb_build_object('amount', w.amount), trim(p_reason));
  return 'rejected';
end $$;

-- Money leaves here: split across the investor's holdings in proportion to their value, dated the
-- current month (withdrawn money does not earn that month's result). Waits until last month is closed,
-- so a loss can never be booked on money already paid out.
create or replace function public.pay_withdrawal(p_id uuid, p_staff uuid, p_tx_ref text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_role  staff_role := staff_money_role(p_staff);
  w       withdrawals%rowtype;
  v_ref   text := upper(regexp_replace(coalesce(p_tx_ref, ''), '\s', '', 'g'));
  v_ym    date := date_trunc('month', now() at time zone 'Asia/Karachi')::date;
  v_prev  date := (date_trunc('month', now() at time zone 'Asia/Karachi') - interval '1 month')::date;
  v_total numeric;
  v_left  numeric;
  v_share numeric;
  h       record;
  v_n     int;
  v_i     int := 0;
begin
  if length(v_ref) < 4 then raise exception 'Enter the payment transaction reference'; end if;
  select * into w from withdrawals where id = p_id for update;
  if not found then raise exception 'Withdrawal not found'; end if;
  if w.status = 'paid' then return jsonb_build_object('status', 'paid', 'already', true); end if;
  if w.status <> 'approved' then raise exception 'Withdrawal is %, it must be approved first', w.status; end if;
  if exists (select 1 from withdrawals where tx_ref = v_ref and id <> w.id) then
    raise exception 'Transaction reference % was already used for another withdrawal', v_ref;
  end if;
  perform pg_advisory_xact_lock(hashtext('c50.wd.' || w.user_id));
  if not kyc_verified(w.user_id) then raise exception 'Investor is no longer KYC verified'; end if;
  if not exists (select 1 from payout_methods where id = w.payout_method_id and disabled_at is null and title_verified) then
    raise exception 'The payout method was removed or is not verified';
  end if;
  if not exists (select 1 from month_closes where ym = v_prev)
     and exists (select 1 from ledger_entries where user_id = w.user_id and ym <= v_prev) then
    raise exception 'Close % before paying withdrawals, so its result is booked first', to_char(v_prev, 'YYYY-MM');
  end if;

  -- holdings and their current values; the largest goes last and takes the rounding remainder
  select coalesce(sum(value), 0), count(*) into v_total, v_n
    from (select sum(amount) as value from ledger_entries
           where user_id = w.user_id and holding_id is not null group by holding_id having sum(amount) > 0) x;
  if v_total < w.amount then raise exception 'Balance no longer covers this withdrawal'; end if;

  v_left := w.amount;
  for h in select holding_id, sum(amount) as value from ledger_entries
            where user_id = w.user_id and holding_id is not null
            group by holding_id having sum(amount) > 0 order by 2, 1 loop
    v_i := v_i + 1;
    v_share := case when v_i = v_n then v_left else least(h.value, round(w.amount * h.value / v_total, 2)) end;
    if v_share > 0 then
      insert into ledger_entries (user_id, holding_id, type, amount, ym, ref_type, ref_id, idempotency_key, meta)
      values (w.user_id, h.holding_id, 'withdrawal', -v_share, v_ym, 'withdrawal', w.id::text,
              format('wd:%s:%s', w.id, h.holding_id),
              jsonb_build_object('source', 'withdrawal', 'tx_ref', v_ref,
                                 'day', extract(day from now() at time zone 'Asia/Karachi')::int));
    end if;
    v_left := v_left - v_share;
  end loop;

  update withdrawals set status = 'paid', tx_ref = v_ref, paid_at = now(), paid_by = p_staff where id = w.id;
  insert into audit_log (actor_id, actor_role, action, entity, entity_id, after)
  values (p_staff, v_role::text, 'withdrawal.paid', 'withdrawals', w.id::text,
          jsonb_build_object('amount', w.amount, 'tx_ref', v_ref, 'ym', to_char(v_ym, 'YYYY-MM')));
  return jsonb_build_object('status', 'paid', 'already', false);
end $$;

-- ---------------------------------------------------------------------- RLS
alter table public.payout_methods enable row level security;
alter table public.withdrawals    enable row level security;

drop policy if exists payout_methods_own_read on public.payout_methods;
create policy payout_methods_own_read on public.payout_methods
  for select to authenticated using (user_id = auth.uid());
drop policy if exists withdrawals_own_read on public.withdrawals;
create policy withdrawals_own_read on public.withdrawals
  for select to authenticated using (user_id = auth.uid());

-- investors never see the encrypted account or its hash, only the hint
revoke select on public.payout_methods from authenticated;
grant select (id, user_id, type, account_hint, bank, title, title_verified, ready_at, disabled_at, created_at)
  on public.payout_methods to authenticated;
revoke insert, update, delete on public.payout_methods, public.withdrawals from anon, authenticated;

revoke execute on function public.ledger_balance(uuid), public.available_to_withdraw(uuid), public.kyc_verified(uuid),
  public.request_withdrawal(uuid, uuid, numeric, timestamptz), public.cancel_withdrawal(uuid, uuid),
  public.staff_money_role(uuid), public.approve_withdrawal(uuid, uuid), public.reject_withdrawal(uuid, uuid, text),
  public.pay_withdrawal(uuid, uuid, text)
  from public, anon, authenticated;
grant execute on function public.ledger_balance(uuid), public.available_to_withdraw(uuid), public.kyc_verified(uuid),
  public.request_withdrawal(uuid, uuid, numeric, timestamptz), public.cancel_withdrawal(uuid, uuid),
  public.approve_withdrawal(uuid, uuid), public.reject_withdrawal(uuid, uuid, text), public.pay_withdrawal(uuid, uuid, text)
  to service_role;


-- ======================================================== demo_user.sql
-- Demo investor account: mobile 300 1234567, password Demo#2026.
-- Safe to re-run: an existing demo account just gets its password reset.
-- Delete this account before launch (PRODUCTION-BRIEF §9).
do $$
declare
  v_phone text := '923001234567';
  v_uid   uuid;
begin
  select id into v_uid from auth.users where phone = v_phone;
  if v_uid is null then
    v_uid := gen_random_uuid();
    insert into auth.users (
      instance_id, id, aud, role, phone, phone_confirmed_at, encrypted_password,
      raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
      confirmation_token, recovery_token, email_change_token_new, email_change,
      phone_change, phone_change_token, email_change_token_current, reauthentication_token)
    values (
      '00000000-0000-0000-0000-000000000000', v_uid, 'authenticated', 'authenticated',
      v_phone, now(), extensions.crypt('Demo#2026', extensions.gen_salt('bf')),
      '{"provider":"phone","providers":["phone"]}',
      jsonb_build_object('full_name', 'Demo Investor', 'email', 'demo@capital50.ai', 'risk_ack_at', now()),
      now(), now(), '', '', '', '', '', '', '', '');
    insert into auth.identities (provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
    values (v_uid::text, v_uid,
            jsonb_build_object('sub', v_uid::text, 'phone', v_phone, 'email_verified', false, 'phone_verified', true),
            'phone', now(), now(), now());
  else
    update auth.users
       set encrypted_password = extensions.crypt('Demo#2026', extensions.gen_salt('bf')),
           phone_confirmed_at = coalesce(phone_confirmed_at, now()),
           updated_at = now()
     where id = v_uid;
  end if;
end $$;

-- Demo money: the same sample deposits the dashboard preview used, followed by real month
-- closes, so the demo dashboard shows figures produced by the production ledger.
-- Re-running adds nothing. purge_demo_data() removes all of it.
do $$
declare
  v_uid uuid;
  v_h   uuid;
  d     record;
  m     date;
begin
  select id into v_uid from auth.users where phone = '923001234567';
  for d in select * from (values ('kitchen', date '2026-07-01', 25000, 1), ('gold', date '2026-07-01', 15000, 1),
                                 ('crypto',  date '2026-07-01', 10000, 1), ('sat',  date '2026-09-01', 20000, 4))
                    as v(slug, ym, amt, day) loop
    insert into public.holdings (user_id, strategy_id)
      select v_uid, id from public.strategies where slug = d.slug
      on conflict (user_id, strategy_id) do nothing;
    select h.id into v_h from public.holdings h join public.strategies s on s.id = h.strategy_id
     where h.user_id = v_uid and s.slug = d.slug;
    if not exists (select 1 from public.ledger_entries where idempotency_key = 'demo:deposit:' || d.slug)
       and not exists (select 1 from public.month_closes where ym >= d.ym) then
      insert into public.ledger_entries (user_id, holding_id, type, amount, ym, ref_type, idempotency_key, meta)
      values (v_uid, v_h, 'deposit', d.amt, d.ym, 'demo_seed', 'demo:deposit:' || d.slug,
              jsonb_build_object('demo', true, 'day', d.day));
    end if;
  end loop;

  for m in select generate_series(date '2026-07-01', date '2026-09-01', interval '1 month')::date loop
    if not exists (select 1 from public.month_closes where ym >= m) then
      perform public.close_month(m);
    end if;
  end loop;
end $$;
